            const y = Math.max(0, Math.min(window.innerHeight - btn.offsetHeight, e.clientY - offsetY));
            btn.style.left = x + "px";
            btn.style.top = y + "px";
            btn.style.right = "auto";
            btn.style.bottom = "auto";
